INSERT INTO `products` (`id`, `slug`, `name`, `category`, `price`, `description`, `full_description`, `thumbnail`, `in_stock`, `sort_order`) VALUES
(1, 'son-dulux-weathershield-colour-protect', 'Sơn Ngoại Thất Dulux Weathershield Colour Protect', 'Sơn Dulux', 'Liên hệ', 'Sơn ngoại thất cao cấp Dulux Weathershield Colour Protect với công nghệ Active Guard chống phai màu tối ưu, chống bám bụi và rêu mốc vượt trội cho khí hậu nhiệt đới.', '<p><strong>Dulux Weathershield Colour Protect</strong> là dòng sơn nước ngoại thất cao cấp nhất của AkzoNobel. Được tích hợp công nghệ Smart Release giải phóng các phân tử thông minh bảo vệ màu sơn gấp 2 lần dưới ánh nắng mặt trời và mưa bão miền biển Vũng Tàu.</p>\n<h4>Ưu điểm vượt trội:</h4>\n<ul>\n  <li>Chống phai màu đỉnh cao, bền màu đến 8 năm.</li>\n  <li>Chống bám bẩn và làm mát tường nhà tới 5 độ C (Keep Cool).</li>\n  <li>Kháng kiềm, kháng nấm mốc và chống loang màu muối hóa.</li>\n  <li>Đạt chứng nhận xanh Singapore Green Building Product.</li>\n</ul>\n<h4>Quy trình thi công:</h4>\n<p>Bột trét ngoại thất Dulux (2 lớp) &rarr; Sơn lót ngoại thất Dulux Weathershield (1 lớp) &rarr; Sơn phủ Dulux Weathershield Colour Protect (2 lớp).</p>', '/uploads/products/dulux-weathershield.png', 1, 0),
(2, 'son-dulux-ambiance-5in1-superflexx', 'Sơn Nội Thất Siêu Cao Cấp Dulux Ambiance 5in1', 'Sơn Dulux', 'Liên hệ', 'Sơn nội thất siêu cao cấp Dulux Ambiance 5in1 mang lại bề mặt láng mịn hoàn hảo, màng sơn co giãn đàn hồi che lấp vết nứt nhỏ và kháng khuẩn bảo vệ sức khỏe.', '<p><strong>Dulux Ambiance 5in1</strong> khẳng định đẳng cấp không gian sống với 5 tính năng bảo vệ toàn diện: bề mặt láng mịn sang trọng, che lấp khe nứt nhỏ, dễ lau chùi, kháng khuẩn và nấm mốc.</p>\n<h4>Tính năng nổi bật:</h4>\n<ul>\n  <li>Màng sơn co giãn Superflexx đàn hồi gấp 3 lần sơn thông thường.</li>\n  <li>Kháng khuẩn tối đa, ngăn ngừa 99\% vi khuẩn có hại bám trên tường.</li>\n  <li>Màu sắc thanh lịch, độ bền màu tuyệt hảo.</li>\n  <li>Không chứa chì, thủy ngân, mùi dịu nhẹ thân thiện môi trường.</li>\n</ul>', '/uploads/products/dulux-ambiance-5in1.png', 1, 1),
(3, 'son-dulux-easyclean-chong-bam-ban', 'Sơn Nội Thất Dulux EasyClean Chống Bám Bẩn', 'Sơn Dulux', 'Liên hệ', 'Sơn nội thất Dulux EasyClean với công nghệ Chống Bám Bẩn Chủ Động ngăn chặn các vết bẩn cứng đầu thấm sâu vào màng sơn, giúp lau chùi dễ dàng.', '<p><strong>Dulux EasyClean</strong> được thiết kế đặc biệt cho các gia đình có trẻ nhỏ. Công nghệ chống bám bẩn chủ động giúp các vết cà phê, nước ngọt, bút chì màu, tương cà có thể lau sạch chỉ bằng khăn ẩm xà phòng mà không làm trôi màng sơn.</p>', '/uploads/products/dulux-easyclean.jpg', 1, 2),
(4, 'chat-chong-tham-dulux-aquatech-vuot-troi', 'Chất Chống Thấm Cao Cấp Dulux Aquatech', 'Sơn Dulux', 'Liên hệ', 'Chất chống thấm tường đứng Dulux Aquatech ứng dụng công nghệ Hydroshield tăng cường liên kết hóa học, ngăn nước thẩm thấu vào cấu trúc tường bê tông.', '<p><strong>Dulux Aquatech</strong> là giải pháp chống thấm tường ngoài hoàn hảo, không cần pha trộn xi măng, thi công trực tiếp nhanh chóng, che lấp các vết rạn nứt chân chim hiệu quả.</p>', '/uploads/products/dulux-aquatech.jpg', 1, 3),
(5, 'son-lot-ngoai-that-dulux-weathershield-chong-kiem', 'Sơn Lót Ngoại Thất Dulux Weathershield Chống Kiềm', 'Sơn Dulux', 'Liên hệ', 'Sơn lót cao cấp ngoài trời Dulux Weathershield ngăn chặn sự kiềm hóa từ xi măng, tăng cường độ bám dính và giữ cho lớp sơn phủ luôn tươi màu.', '<p>Sơn lót ngoài trời Dulux là lớp màng đệm thiết yếu giúp trung hòa nồng độ pH của tường trát xi măng, chống kiềm hóa muối hóa gây ố vàng và bong tróc lớp sơn ngoài.</p>', '/uploads/products/dulux-weathershield-primer.jpg', 1, 4),
(6, 'son-jotun-jotashield-ben-mau-toi-uu', 'Sơn Ngoại Thất Jotun Jotashield Bền Màu Tối Ưu', 'Sơn Jotun', 'Liên hệ', 'Dòng sơn ngoại thất cao cấp nhất của Jotun với công nghệ chất tạo màu tiên tiến, chống tia UV vượt trội và chống bám bụi bẩn tối ưu.', '<p><strong>Jotun Jotashield Bền Màu Tối Ưu</strong> được thử nghiệm và chứng minh độ bền màu vượt thời gian tại vùng khí hậu khắc nghiệt miền duyên hải. Khả năng kháng tia cực tím tối đa giúp ngôi nhà luôn rạng rỡ như mới.</p>\n<h4>Đặc tính kỹ thuật:</h4>\n<ul>\n  <li>Kháng tia cực tím UV gấp 2 lần.</li>\n  <li>Chống bám bụi bẩn, tự rửa sạch màng sơn khi trời mưa.</li>\n  <li>Ngăn ngừa nấm mốc và rêu phong triệt để.</li>\n  <li>Bảo vệ công trình lên đến 12 năm.</li>\n</ul>', '/uploads/products/jotun-jotashield.jpg', 1, 5),
(7, 'son-jotun-majestic-dep-hoan-hao', 'Sơn Nội Thất Cao Cấp Jotun Majestic Đẹp Hoàn Hảo', 'Sơn Jotun', 'Liên hệ', 'Sơn nội thất Majestic Đẹp Hoàn Hảo mang đến màu sắc rực rỡ, bề mặt láng mịn sang trọng và khả năng lau chùi vết bẩn dễ dàng.', '<p><strong>Jotun Majestic Đẹp Hoàn Hảo</strong> kết hợp công nghệ màu đích thực của Jotun, giúp tái hiện chính xác từng gam màu sắc nét, ấm cúng. Sơn không mùi, an toàn tuyệt đối cho trẻ em và người già.</p>', '/uploads/products/jotun-majestic.jpg', 1, 6),
(8, 'son-jotun-waterguard-chong-tham', 'Sơn Chống Thấm Tường Đứng Jotun WaterGuard', 'Sơn Jotun', 'Liên hệ', 'Sơn chống thấm gốc acrylic biến tính Jotun WaterGuard bảo vệ tường nhà khỏi sự xâm nhập của nước mưa, độ đàn hồi cao che phủ vết nứt nhỏ.', '<p><strong>Jotun WaterGuard</strong> không cần pha xi măng, màu sắc phong phú (xám nhạt, xám đậm, vàng kem). Màng sơn đàn hồi cao giúp ngăn chặn rêu mốc và ẩm mốc chân tường hiệu quả.</p>', '/uploads/products/jotun-waterguard.jpg', 1, 7),
(9, 'son-jotun-essence-de-lau-chui', 'Sơn Nội Thất Jotun Essence Dễ Lau Chùi', 'Sơn Jotun', 'Liên hệ', 'Sơn nội thất Jotun Essence dễ lau chùi, độ che phủ cao, mùi nhẹ, thân thiện với môi trường và mang lại bề mặt tường sáng bóng mịn màng.', '<p>Jotun Essence Dễ Lau Chùi là sự lựa chọn kinh tế thông minh cho ngôi nhà của bạn. Các vết bẩn thông thường như cà phê, vết ố bẩn nhẹ dễ dàng được làm sạch mà không làm trôi màu sơn.</p>', '/uploads/products/jotun-essence.jpg', 1, 8),
(10, 'son-lot-jotun-ultra-primer-chong-kiem', 'Sơn Lót Cao Cấp Jotun Ultra Primer Kháng Kiềm', 'Sơn Jotun', 'Liên hệ', 'Sơn lót gốc nước cao cấp Jotun Ultra Primer có độ bám dính tuyệt hảo trên bề mặt bê tông mới và tường ẩm, chống kiềm hóa muối hóa cực mạnh.', '<p>Jotun Ultra Primer có khả năng thi công ngay trên tường bê tông còn độ ẩm cao (sau 3 ngày trát), giúp đẩy nhanh tiến độ hoàn thiện công trình mà vẫn đảm bảo độ bền tối đa.</p>', '/uploads/products/jotun-ultra-primer.jpg', 1, 9),
(11, 'chat-chong-tham-cao-cap-kova-ct-11a-plus', 'Chất Chống Thấm Cao Cấp Kova CT-11A Plus Tường', 'Sơn Kova', 'Liên hệ', 'Hợp chất chống thấm số 1 thị trường Việt Nam Kova CT-11A Plus có khả năng ngăn chặn nước thẩm thấu tuyệt hảo từ bên ngoài vào trong cấu trúc xi măng.', '<p><strong>Kova CT-11A Plus Tường</strong> được tổng hợp từ Acrylonitrile và Alkylsiloxan, tạo liên kết chặt chẽ với bê tông và vữa xi măng. Độ bền chống thấm đã được thử nghiệm thực tế lên đến 15 năm.</p>\n<h4>Ưu điểm:</h4>\n<ul>\n  <li>Chống thấm tuyệt đối cho tường ngoài, sàn ban công, sân thượng.</li>\n  <li>Chịu mài mòn, chịu nước mặn, kháng kiềm cực cao.</li>\n  <li>Không chứa chất độc hại, an toàn tuyệt đối cho người thi công và người sử dụng.</li>\n</ul>', '/uploads/products/kova-ct11a.jpg', 1, 10),
(12, 'son-bong-noi-that-cao-cap-kova-k-5500', 'Sơn Bóng Cao Cấp Trong Nhà Kova K-5500', 'Sơn Kova', 'Liên hệ', 'Sơn nước nội thất bóng cao cấp Kova K-5500 cho màng sơn nhẵn bóng lộng lẫy, lau chùi vết bẩn dễ dàng và kháng khuẩn bảo vệ không gian sống.', '<p>Kova K-5500 là dòng sơn nội thất cao cấp của Kova, bề mặt bóng lộng lẫy giúp phản chiếu ánh sáng tự nhiên, tăng vẻ sang trọng cho phòng khách, phòng ngủ và biệt thự cao cấp.</p>', '/uploads/products/kova-k5500.jpg', 1, 11),
(13, 'son-bong-ngoai-that-kova-k-5501', 'Sơn Bóng Cao Cấp Ngoài Trời Kova K-5501', 'Sơn Kova', 'Liên hệ', 'Sơn ngoại thất cao cấp Kova K-5501 màng sơn bóng đẹp, chống thấm nước, chống rêu mốc và tia UV, giữ màu sắc công trình luôn tươi mới.', '<p>Kova K-5501 là dòng sơn bóng ngoại thất danh tiếng chịu được nắng mưa nhiệt đới gió mùa của Vũng Tàu. Khả năng đàn hồi giúp màng sơn không bị nứt chân chim theo thời gian.</p>', '/uploads/products/kova-k5501.jpg', 1, 12),
(14, 'son-lot-khang-kiem-ngoai-troi-kova-k-209', 'Sơn Lót Kháng Kiềm Ngoài Trời Kova K-209', 'Sơn Kova', 'Liên hệ', 'Sơn lót kháng kiềm ngoài trời Kova K-209 bảo vệ lớp sơn phủ không bị loang ố do kiềm trong vữa hồ và độ ẩm cao.', '<p>Sơn lót Kova K-209 có độ bám dính cực tốt vào bề mặt bê tông, tạo lớp màng ngăn cản sự thấm ẩm và kiềm hóa, giữ cho lớp sơn bóng ngoài trời luôn sáng đẹp.</p>', '/uploads/products/kova-k209-primer.png', 1, 13),
(15, 'son-nippon-weathergard-plus', 'Sơn Ngoại Thất Siêu Bền Nippon WeatherGard Plus+', 'Sơn Nippon', 'Liên hệ', 'Sơn ngoại thất cao cấp Nippon WeatherGard Plus+ với công nghệ Micro-gel chống nóng phản xạ nhiệt, chống rêu mốc và bảo vệ màu sắc vượt trội.', '<p><strong>Nippon WeatherGard Plus+</strong> là sản phẩm sơn nước ngoại thất cao cấp của tập đoàn Nippon Paint Nhật Bản. Công nghệ tiên tiến giúp giảm nhiệt độ bề mặt tường tới 5 độ C, tiết kiệm điện năng cho điều hòa.</p>', '/uploads/products/nippon-weathergard.jpg', 1, 14),
(16, 'son-nippon-odour-less-all-in-one', 'Sơn Nội Thất Không Mùi Nippon Odour-less All-in-1', 'Sơn Nippon', 'Liên hệ', 'Sơn nội thất Nippon Odour-less All-in-1 gần như không mùi trong quá trình thi công và sau khi sơn, hàm lượng VOC cực thấp, an toàn tuyệt đối.', '<p>Dòng sơn cao cấp thân thiện với môi trường của Nhật Bản, phù hợp sơn cho phòng ngủ, trường học, bệnh viện, nhà hàng nơi cần đưa vào sử dụng ngay sau khi thi công.</p>', '/uploads/products/nippon-odourless.jpg', 1, 15),
(17, 'son-nippon-matex-noi-that', 'Sơn Nội Thất Kinh Tế Nippon Matex', 'Sơn Nippon', 'Liên hệ', 'Sơn nước trong nhà Nippon Matex đem lại độ phủ cao, màng sơn mịn màng, dễ thi công và có chi phí vô cùng kinh tế.', '<p>Nippon Matex là dòng sơn nội thất thông dụng nhất của Nippon Paint, lý tưởng cho tường và trần thạch cao nội thất với màu sắc đa dạng và độ phủ tuyệt vời.</p>', '/uploads/products/nippon-matex.jpg', 1, 16),
(18, 'son-lot-nippon-weathergard-sealer', 'Sơn Lót Ngoại Thất Nippon WeatherGard Sealer', 'Sơn Nippon', 'Liên hệ', 'Sơn lót kháng kiềm ngoại thất Nippon WeatherGard Sealer ngăn ngừa sự phá hủy của kiềm và phấn hóa xi măng, tăng cường độ bám dính.', '<p>Được pha chế đặc biệt với hàm lượng keo acrylic cao, Nippon WeatherGard Sealer thẩm thấu sâu vào bề mặt tường bê tông, tạo chân bám vững chắc cho lớp sơn phủ.</p>', '/uploads/products/nippon-sealer.jpg', 1, 17),
(19, 'son-mykolor-grand-quartz-feel', 'Sơn Ngoại Thất Siêu Bóng Mykolor Grand Quartz Feel', 'Sơn Mykolor', 'Liên hệ', 'Sơn ngoại thất siêu bóng Mykolor Grand Quartz Feel sang trọng, chống bám bụi bẩn, chống rêu mốc và chịu được thời tiết nhiệt đới khắc nghiệt.', '<p><strong>Mykolor Grand Quartz Feel</strong> là dòng sơn ngoại thất đỉnh cao của 4 Oranges. Màng sơn siêu bóng sáng lấp lánh như pha lê, ngăn chặn hoàn toàn bụi bẩn bám dính vào bề mặt tường nhà.</p>', '/uploads/products/mykolor-grand-quartz.jpg', 1, 18),
(20, 'son-mykolor-touch-ilka-finish', 'Sơn Nội Thất Siêu Láng Mịn Mykolor Touch Ilka Finish', 'Sơn Mykolor', 'Liên hệ', 'Sơn nội thất láng mịn cao cấp Mykolor Touch Ilka Finish với hơn 1040 màu sắc hiện đại, mang lại vẻ đẹp quý phái cho không gian nội thất.', '<p>Bộ sưu tập sơn Mykolor Touch được các kiến trúc sư yêu thích bởi bảng màu tinh tế, độ mịn màng như lụa và khả năng lau chùi vết bẩn hiệu quả.</p>', '/uploads/products/mykolor-touch-ilka.jpg', 1, 19),
(21, 'hop-chat-chong-tham-mykolor-water-seal', 'Hợp Chất Chống Thấm Pha Xi Măng Mykolor Water Seal', 'Sơn Mykolor', 'Liên hệ', 'Chất chống thấm pha xi măng Mykolor Water Seal bảo vệ tối ưu chống ẩm và thấm dột cho tường đứng, bể nước, sân thượng và sàn nhà vệ sinh.', '<p>Hợp chất chống thấm chuyên dụng Mykolor liên kết chắc chắn với xi măng cát tạo nên lớp màng ngăn nước liên tục, bền vững cùng tuổi thọ công trình.</p>', '/uploads/products/mykolor-water-seal.jpg', 1, 20),
(22, 'son-nuoc-ngoai-that-maxilite-tough', 'Sơn Nước Ngoại Thất Maxilite Tough Bền Màu', 'Sơn Maxilite', 'Liên hệ', 'Sơn ngoại thất Maxilite Tough từ AkzoNobel với công nghệ SuperLock chống bong tróc, màu sắc bền đẹp và chi phí đầu tư vô cùng hợp lý.', '<p><strong>Maxilite Tough</strong> là dòng sơn nước ngoài trời kinh tế bán chạy số một cho các công trình nhà phố, dãy trọ, văn phòng cho thuê với độ bền màu và màng sơn đanh chắc.</p>', '/uploads/products/maxilite-tough.png', 1, 21),
(23, 'son-nuoc-trong-nha-maxilite-total', 'Sơn Nước Trong Nhà Maxilite Total', 'Sơn Maxilite', 'Liên hệ', 'Sơn nội thất Maxilite Total có độ phủ cao, màng sơn mịn đẹp, màu sắc phong phú, giải pháp tiết kiệm hàng đầu cho ngôi nhà bạn.', '<p>Maxilite Total trong nhà cho bề mặt tường sáng láng mịn, che lấp các khuyết điểm nhỏ của tường trát hồ, thi công nhẹ tay và nhanh khô.</p>', '/uploads/products/maxilite-total.png', 1, 22),
(24, 'son-lot-khang-kiem-maxilite', 'Sơn Lót Kháng Kiềm Maxilite', 'Sơn Maxilite', 'Liên hệ', 'Sơn lót kháng kiềm Maxilite bảo vệ màng sơn phủ không bị loang ố kiềm hóa, gia tăng độ bám dính và tiết kiệm lượng sơn phủ bề mặt.', '<p>Sơn lót kháng kiềm Maxilite là bước chuẩn bị bề mặt hoàn hảo cho các công trình dùng sơn Maxilite hoặc Dulux, giúp tăng tuổi thọ toàn bộ hệ sơn.</p>', '/uploads/products/maxilite-primer.jpg', 1, 23),
(25, 'son-ngoai-that-sieu-bong-nasun-diamond-shield', 'Sơn Ngoại Thất Siêu Bóng NaSun Diamond Shield', 'Sơn NaSun', 'Liên hệ', 'Sơn ngoại thất siêu bóng NaSun Diamond Shield công nghệ hạt Nano Kim Cương tự làm sạch, chống bám bụi và kháng kiềm muối ven biển cực tốt.', '<p><strong>Sơn Mặt Trời Việt NaSun Diamond Shield</strong> là dòng sản phẩm cao cấp được đặc chế riêng cho khí hậu nắng gió và hơi ẩm mặn của Vũng Tàu. Màng sơn siêu bóng sáng như ngọc trai, chống rêu mốc và tia UV bền vững trên 10 năm.</p>\n<h4>Tính năng kỹ thuật:</h4>\n<ul>\n  <li>Công nghệ hạt Nano chống bám bẩn tự rửa sạch bề mặt.</li>\n  <li>Chống kiềm hóa, muối hóa và ố vàng cực mạnh.</li>\n  <li>Màu sắc tươi sáng, đa dạng lựa chọn theo phong thủy.</li>\n</ul>', '/uploads/products/nasun-diamond-shield.jpg', 1, 24),
(26, 'son-noi-that-khang-khuan-nasun-nano-silver', 'Sơn Nội Thất Kháng Khuẩn NaSun Nano Silver', 'Sơn NaSun', 'Liên hệ', 'Sơn nội thất cao cấp NaSun Nano Silver chứa các ion bạc kháng khuẩn 99.9\%, lau chùi vết bẩn vượt trội, bảo vệ sức khỏe cho cả gia đình.', '<p>NaSun Nano Silver tạo nên không gian sống xanh, trong lành và thư thái. Màng sơn nhẵn mịn, màu sắc tinh tế, dễ lau chùi các vết bẩn sinh hoạt hàng ngày mà không sợ bay màu.</p>', '/uploads/products/nasun-nano-silver.png', 1, 25),
(27, 'chat-chong-tham-da-nang-nasun-ct-01', 'Hợp Chất Chống Thấm Đa Năng NaSun CT-01', 'Sơn NaSun', 'Liên hệ', 'Chất chống thấm đa năng NaSun CT-01 pha xi măng chuyên trị thấm nứt sàn mái, ban công, vách hông nhà phố và nhà vệ sinh triệt để.', '<p>NaSun CT-01 tạo liên kết tinh thể bám sâu vào lỗ rỗng mao dẫn của bê tông, ngăn chặn tuyệt đối nguồn nước ngấm vào kết cấu công trình xây dựng.</p>', '/uploads/products/nasun-ct01.png', 1, 26),
(28, 'son-ngoai-that-toa-nanoshield', 'Sơn Ngoại Thất TOA NanoShield Chống Bám Bẩn', 'Sơn TOA', 'Liên hệ', 'Sơn nước ngoại thất cao cấp TOA NanoShield với công nghệ Nano từ Đức, chống bám bẩn, chống rêu mốc và bền màu trước thời tiết nhiệt đới.', '<p><strong>TOA NanoShield</strong> sở hữu các hạt Nano Silicon có tính năng đẩy lùi nước và chất bẩn, giúp bề mặt tường nhà luôn sạch bóng như mới sau mỗi cơn mưa rào.</p>', '/uploads/products/toa-nanoshield.jpg', 1, 27),
(29, 'son-noi-that-toa-nanoclean', 'Sơn Nội Thất TOA NanoClean Kháng Khuẩn', 'Sơn TOA', 'Liên hệ', 'Sơn nội thất TOA NanoClean với các hạt Nano Silver kháng khuẩn vượt trội, bề mặt nhẵn mịn, lau chùi vết bẩn dễ dàng.', '<p>Sơn nội thất TOA NanoClean diệt khuẩn đến 99.9\%, bảo vệ sức khỏe cho các thành viên trong gia đình, mùi thơm dễ chịu và an toàn cho môi trường sống.</p>', '/uploads/products/toa-nanoclean.jpg', 1, 28);
